create table public.qc_inspections(qc_inspection_id uuid primary key default gen_random_uuid(),production_batch_id uuid not null references public.production_batches(production_batch_id),inspection_date date not null default current_date,inspector_id uuid references public.operators(operator_id),inspection_type text not null default 'IN_PROCESS',sample_size int,width_check_result text,pull_ratio_check_result text,size_check_result text,overall_result text not null check(overall_result in('PASS','HOLD','REJECT')),physical_sample_attached boolean not null default false,notes text,created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text);
create table public.qc_defects(qc_defect_id uuid primary key default gen_random_uuid(),qc_inspection_id uuid not null references public.qc_inspections(qc_inspection_id) on delete cascade,defect_type text not null,defect_severity text check(defect_severity in('MINOR','MAJOR','CRITICAL')),quantity_affected numeric,uom_id uuid references public.uoms(uom_id),disposition text check(disposition in('REWORK','SCRAP','CONCESSION')),notes text,created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text);
create or replace function public.submit_qc_inspection(p_batch uuid,p_inspector uuid,p_type text,p_sample_size int,p_width text,p_pull text,p_size text,p_result text,p_sample_attached boolean,p_notes text,p_defects jsonb default'[]')returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid;v_order uuid;v_defect jsonb;begin if not has_factory_role(auth.uid(),array['admin','quality'])then raise exception'not authorized';end if;if p_result not in('PASS','HOLD','REJECT')then raise exception'invalid result';end if;select production_order_id into v_order from production_batches where production_batch_id=p_batch;if not found then raise exception'batch not found';end if;insert into qc_inspections(production_batch_id,inspector_id,inspection_type,sample_size,width_check_result,pull_ratio_check_result,size_check_result,overall_result,physical_sample_attached,notes,created_by)values(p_batch,p_inspector,p_type,p_sample_size,p_width,p_pull,p_size,p_result,p_sample_attached,p_notes,auth.uid()::text)returning qc_inspection_id into v_id;for v_defect in select value from jsonb_array_elements(p_defects)loop insert into qc_defects(qc_inspection_id,defect_type,defect_severity,quantity_affected,disposition,notes,created_by)values(v_id,v_defect->>'defect_type',v_defect->>'severity',nullif(v_defect->>'quantity','')::numeric,nullif(v_defect->>'disposition',''),v_defect->>'notes',auth.uid()::text);end loop;update production_orders set status=case when p_result='PASS'then'QC_APPROVED'else'QC_HOLD'end,updated_at=now(),updated_by=auth.uid()::text where production_order_id=v_order;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),case when p_result='PASS'then'QC Released'else'QC Hold'end,'qc_inspections',v_id,jsonb_build_object('result',p_result,'batch_id',p_batch));return v_id;end $$;
alter table public.production_orders drop constraint production_orders_status_check;alter table public.production_orders add constraint production_orders_status_check check(status in('ORDER_CONFIRMED','PRODUCTION_PLANNED','MATERIALS_PENDING','MATERIALS_READY','MACHINE_ASSIGNED','IN_SETUP','IN_PRODUCTION','ON_HOLD','QC_PENDING','QC_HOLD','QC_APPROVED','CANCELLED'));
alter table public.qc_inspections enable row level security;alter table public.qc_defects enable row level security;create policy factory_read_qc on public.qc_inspections for select using(has_factory_role(auth.uid(),array['admin','production_manager','supervisor','quality','accounts','viewer']));create policy factory_read_qc_defects on public.qc_defects for select using(has_factory_role(auth.uid(),array['admin','production_manager','supervisor','quality','accounts','viewer']));grant execute on function public.submit_qc_inspection(uuid,uuid,text,int,text,text,text,text,boolean,text,jsonb)to authenticated;
